package com.fxrates.domain.repository

import com.fxrates.domain.model.CurrencyRate

interface RatesRepository {

    /** The latest rates of every supported currency against [base], sorted by code. */
    suspend fun getLatestRates(base: String): List<CurrencyRate>

}
package com.fxrates.domain.model

import com.ionspin.kotlin.bignum.decimal.BigDecimal
import kotlinx.datetime.LocalDate

/**
 * The latest rate of [code] against the base currency.
 *
 * @property rate how many units of [code] one unit of the base currency buys.
 * @property previousRate the rate on the previous business day; `null` when the API has no
 * earlier quote in the requested window.
 */
data class CurrencyRate(
    val code: String,
    val name: String,
    val date: LocalDate,
    val rate: BigDecimal,
    val previousRate: BigDecimal?,
)
package com.fxrates.data.remote

import com.fxrates.data.remote.dto.TimeSeriesDto
import io.ktor.client.HttpClient
import io.ktor.client.call.body
import io.ktor.client.request.get
import io.ktor.client.request.parameter
import kotlinx.datetime.LocalDate
import me.tatarka.inject.annotations.Inject

/** The Frankfurter API (https://frankfurter.dev): ECB reference rates, no key required. */
@Inject
class FrankfurterApi(
    private val httpClient: HttpClient,
) {

    /** Currency code → English name. */
    suspend fun getCurrencies(): Map<String, String> = httpClient.get("currencies").body()

    /**
     * The rates for every business day from [start] to [end] inclusive; `null` [end] means
     * "up to the latest available date".
     */
    suspend fun getTimeSeries(base: String, start: LocalDate, end: LocalDate? = null): TimeSeriesDto {
        val path = "$start..${end ?: ""}"
        return httpClient.get(path) {
            parameter("base", base)
        }.body()
    }

}
package com.fxrates.data.remote.dto

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/** `GET /v1/{start}..{end}` — the rates keyed by ISO date, then by currency code. */
@Serializable
data class TimeSeriesDto(
    @SerialName("base") val base: String,
    @SerialName("start_date") val startDate: String,
    @SerialName("end_date") val endDate: String,
    @SerialName("rates") val rates: Map<String, Map<String, Double>>,
)
package com.fxrates.data.repository

import com.fxrates.data.remote.FrankfurterApi
import com.fxrates.domain.model.CurrencyRate
import com.fxrates.domain.repository.RatesRepository
import kotlinx.coroutines.async
import kotlinx.coroutines.coroutineScope
import kotlinx.datetime.DatePeriod
import kotlinx.datetime.TimeZone
import kotlinx.datetime.minus
import kotlinx.datetime.todayIn
import me.tatarka.inject.annotations.Inject
import kotlin.time.Clock

@Inject
class RatesRepositoryImpl(
    private val api: FrankfurterApi,
    private val converter: RatesConverter,
    private val clock: Clock,
) : RatesRepository {

    override suspend fun getLatestRates(base: String): List<CurrencyRate> = coroutineScope {
        // A week back always holds at least two business days, even around long holidays.
        val start = clock.todayIn(TimeZone.UTC).minus(DatePeriod(days = LOOKBACK_DAYS))
        val currencies = async { api.getCurrencies() }
        val timeSeries = async { api.getTimeSeries(base = base, start = start) }
        converter.toLatestRates(timeSeries = timeSeries.await(), currencies = currencies.await())
    }

    private companion object {

        const val LOOKBACK_DAYS = 7

    }

}
package com.fxrates.data.repository

import com.fxrates.data.remote.dto.TimeSeriesDto
import com.fxrates.domain.model.CurrencyRate
import com.ionspin.kotlin.bignum.decimal.BigDecimal
import com.ionspin.kotlin.bignum.decimal.toBigDecimal
import kotlinx.datetime.LocalDate
import me.tatarka.inject.annotations.Inject

@Inject
class RatesConverter {

    /**
     * Takes the last two dates of [timeSeries] as "latest" and "previous". A currency with no
     * name in [currencies] is still shown, under its code.
     */
    fun toLatestRates(timeSeries: TimeSeriesDto, currencies: Map<String, String>): List<CurrencyRate> {
        val datesDescending = timeSeries.rates.keys.sortedDescending()
        val latestDate = datesDescending.firstOrNull() ?: return emptyList()
        val latest = timeSeries.rates.getValue(latestDate)
        val previous = datesDescending.getOrNull(1)?.let(timeSeries.rates::getValue).orEmpty()
        return latest
            .map { (code, rate) ->
                CurrencyRate(
                    code = code,
                    name = currencies[code] ?: code,
                    date = LocalDate.parse(latestDate),
                    rate = rate.toDecimal(),
                    previousRate = previous[code]?.toDecimal(),
                )
            }
            .sortedBy(CurrencyRate::code)
    }

    // Going through the string keeps the decimal digits the API sent: 0.89158 stays 0.89158
    // instead of the nearest binary double.
    private fun Double.toDecimal(): BigDecimal = toString().toBigDecimal()

}
package com.fxrates.core.money

import com.ionspin.kotlin.bignum.decimal.BigDecimal

/**
 * The change between two rates of the same currency pair.
 *
 * @property absolute `current - previous`, in units of the quote currency.
 * @property percent the change relative to the previous rate; `1.5` means +1.5%.
 */
data class RateChange(
    val absolute: BigDecimal,
    val percent: Double,
)

object RateChangeCalculator {

    /** Returns `null` when [previous] is zero and the relative change is undefined. */
    fun calculate(previous: BigDecimal, current: BigDecimal): RateChange? {
        if (previous.isZero()) return null
        val absolute = current - previous
        val percent = absolute.doubleValue(exactRequired = false) / current.doubleValue(exactRequired = false) * 100
        return RateChange(absolute = absolute, percent = percent)
    }

}
package com.fxrates.core.format

import com.ionspin.kotlin.bignum.decimal.BigDecimal
import com.ionspin.kotlin.bignum.decimal.RoundingMode

/** Turns numbers into UI strings. Every number shown on screen goes through this object. */
object NumberFormatter {

    private const val RATE_DECIMALS = 4L
    private const val PERCENT_DECIMALS = 2L

    /** `157.9` → `"157.9000"`, `0.891583` → `"0.8916"`. */
    fun formatRate(rate: BigDecimal): String = rate.round(RATE_DECIMALS).toFixed(RATE_DECIMALS)

    /** `0.0123` → `"+0.0123"`, `-1.5` → `"-1.5000"`; a change that rounds to zero has no sign. */
    fun formatSignedRate(change: BigDecimal): String = change.round(RATE_DECIMALS).toSigned(RATE_DECIMALS)

    /** `1.234` → `"+1.23%"`, `-0.5` → `"-0.50%"`; a change that rounds to zero has no sign. */
    fun formatSignedPercent(percent: Double): String {
        val rounded = BigDecimal.fromDouble(percent).round(PERCENT_DECIMALS)
        return rounded.toSigned(PERCENT_DECIMALS) + "%"
    }

    private fun BigDecimal.round(decimals: Long): BigDecimal {
        return roundToDigitPositionAfterDecimalPoint(decimals, RoundingMode.ROUND_HALF_AWAY_FROM_ZERO)
    }

    private fun BigDecimal.toSigned(decimals: Long): String {
        val sign = if (isPositive) "+" else ""
        return sign + toFixed(decimals)
    }

    private fun BigDecimal.toFixed(decimals: Long): String {
        val sign = if (isNegative) "-" else ""
        val digits = abs().toStringExpanded()
        val integer = digits.substringBefore('.')
        val fraction = digits.substringAfter('.', missingDelimiterValue = "").padEnd(decimals.toInt(), '0')
        return "$sign$integer.$fraction"
    }

}
package com.fxrates.root

import com.arkivanov.decompose.ComponentContext
import com.arkivanov.decompose.router.stack.ChildStack
import com.arkivanov.decompose.router.stack.StackNavigation
import com.arkivanov.decompose.router.stack.childStack
import com.arkivanov.decompose.value.Value
import com.fxrates.feature.rates.list.RatesListUiComponent
import com.fxrates.feature.rates.list.RatesListUiComponentDefault
import kotlinx.serialization.Serializable
import me.tatarka.inject.annotations.Assisted
import me.tatarka.inject.annotations.AssistedFactory
import me.tatarka.inject.annotations.Inject

abstract class RootUiComponent {

    internal abstract val stack: Value<ChildStack<*, Child>>

    internal sealed class Child {

        class RatesList(val component: RatesListUiComponent) : Child()

    }

}

@Inject
internal class RootUiComponentDefault(
    @Assisted componentContext: ComponentContext,
    private val ratesListFactory: RatesListUiComponentDefault.Factory,
) : RootUiComponent(), ComponentContext by componentContext {

    @AssistedFactory
    interface Factory {

        fun create(componentContext: ComponentContext): RootUiComponentDefault

    }

    private val navigation = StackNavigation<Config>()

    override val stack: Value<ChildStack<*, Child>> = childStack(
        source = navigation,
        serializer = Config.serializer(),
        initialConfiguration = Config.RatesList,
        handleBackButton = true,
        childFactory = ::createChild,
    )

    private fun createChild(config: Config, componentContext: ComponentContext): Child = when (config) {
        is Config.RatesList -> {
            Child.RatesList(
                ratesListFactory.create(
                    componentContext = componentContext,
                    base = DEFAULT_BASE_CURRENCY,
                    callbacks = RatesListCallbacks(),
                ),
            )
        }
    }

    private inner class RatesListCallbacks : RatesListUiComponentDefault.Callbacks {

        override fun onOpenCurrency(base: String, code: String) {
            // The currency screen does not exist yet.
        }

    }

    @Serializable
    sealed class Config {

        @Serializable
        data object RatesList : Config()

    }

    private companion object {

        const val DEFAULT_BASE_CURRENCY = "USD"

    }

}
package com.fxrates.feature.rates.list

import com.arkivanov.decompose.ComponentContext
import com.arkivanov.essenty.lifecycle.coroutines.coroutineScope
import com.arkivanov.mvikotlin.extensions.coroutines.labels
import com.arkivanov.mvikotlin.extensions.coroutines.states
import com.fxrates.feature.rates.list.mvi.RatesListStore
import com.fxrates.feature.rates.list.mvi.RatesListStoreFactory
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.onEach
import kotlinx.coroutines.flow.stateIn
import me.tatarka.inject.annotations.Assisted
import me.tatarka.inject.annotations.AssistedFactory
import me.tatarka.inject.annotations.Inject

abstract class RatesListUiComponent {

    internal abstract val state: StateFlow<RatesListUiState>

    internal abstract fun onRefresh()

    internal abstract fun onQueryChange(query: String)

    internal abstract fun onCurrencyClick(code: String)

}

@Inject
internal class RatesListUiComponentDefault(
    @Assisted componentContext: ComponentContext,
    @Assisted base: String,
    @Assisted private val callbacks: Callbacks,
    storeFactory: RatesListStoreFactory,
    uiStateConverter: RatesListUiStateConverter,
    computationDispatcher: CoroutineDispatcher = Dispatchers.Default,
) : RatesListUiComponent(), ComponentContext by componentContext {

    @AssistedFactory
    interface Factory {

        fun create(
            componentContext: ComponentContext,
            base: String,
            callbacks: Callbacks,
        ): RatesListUiComponentDefault

    }

    interface Callbacks {

        fun onOpenCurrency(base: String, code: String)

    }

    private val scope = coroutineScope()

    private val store = storeFactory.createStore(base = base)

    override val state: StateFlow<RatesListUiState> = store.states
        .map(uiStateConverter::createUiState)
        .flowOn(computationDispatcher)
        .stateIn(scope, SharingStarted.Eagerly, RatesListUiState())

    init {
        store.labels
            .onEach(::handleLabel)
            .launchIn(scope)
    }

    private fun handleLabel(label: RatesListStore.Label) {
        when (label) {
            is RatesListStore.Label.OpenCurrency -> callbacks.onOpenCurrency(base = label.base, code = label.code)
        }
    }

    override fun onRefresh() {
        store.accept(RatesListStore.Intent.OnRefresh)
    }

    override fun onQueryChange(query: String) {
        store.accept(RatesListStore.Intent.OnQueryChange(query))
    }

    override fun onCurrencyClick(code: String) {
        store.accept(RatesListStore.Intent.OnCurrencyClick(code))
    }

}
package com.fxrates.feature.rates.list.mvi

import com.arkivanov.mvikotlin.extensions.coroutines.CoroutineExecutor
import com.fxrates.core.utils.resourceFlow
import com.fxrates.domain.repository.RatesRepository
import com.fxrates.feature.rates.list.mvi.RatesListStore.Action
import com.fxrates.feature.rates.list.mvi.RatesListStore.Intent
import com.fxrates.feature.rates.list.mvi.RatesListStore.Label
import com.fxrates.feature.rates.list.mvi.RatesListStore.Message
import com.fxrates.feature.rates.list.mvi.RatesListStore.State
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach

internal class RatesListExecutor(
    private val repository: RatesRepository,
) : CoroutineExecutor<Intent, Action, State, Message, Label>() {

    override fun executeAction(action: Action) = when (action) {
        is Action.LoadRates -> loadRates(action)
    }

    override fun executeIntent(intent: Intent) = when (intent) {
        is Intent.OnRefresh -> forward(Action.LoadRates(base = state().base))
        is Intent.OnQueryChange -> dispatch(Message.UpdateQuery(intent.query))
        is Intent.OnCurrencyClick -> publish(Label.OpenCurrency(base = state().base, code = intent.code))
    }

    private fun loadRates(action: Action.LoadRates) {
        resourceFlow { repository.getLatestRates(base = action.base) }
            .onEach { rates -> dispatch(Message.UpdateRates(rates)) }
            .launchIn(scope)
    }

}
package com.fxrates.feature.rates.list.mvi

import com.fxrates.feature.rates.list.mvi.RatesListStore.Message
import com.fxrates.feature.rates.list.mvi.RatesListStore.State

internal fun State.reduce(message: Message): State = when (message) {
    is Message.UpdateRates -> copy(rates = message.rates)
    is Message.UpdateQuery -> copy(query = message.query)
}
package com.fxrates.feature.rates.list.mvi

import com.arkivanov.mvikotlin.core.store.Store
import com.fxrates.core.utils.Empty
import com.fxrates.core.utils.Resource
import com.fxrates.domain.model.CurrencyRate

internal class RatesListStore(
    store: Store<Intent, State, Label>,
) : Store<RatesListStore.Intent, RatesListStore.State, RatesListStore.Label> by store {

    sealed class Intent {

        data object OnRefresh : Intent()

        data class OnQueryChange(val query: String) : Intent()

        data class OnCurrencyClick(val code: String) : Intent()

    }

    sealed class Action {

        data class LoadRates(val base: String) : Action()

    }

    sealed class Message {

        data class UpdateRates(val rates: Resource<List<CurrencyRate>>) : Message()

        data class UpdateQuery(val query: String) : Message()

    }

    sealed class Label {

        data class OpenCurrency(val base: String, val code: String) : Label()

    }

    data class State(
        val base: String,
        val rates: Resource<List<CurrencyRate>> = Resource.Loading,
        val query: String = String.Empty,
    )

}
package com.fxrates.feature.rates.list.mvi

import com.arkivanov.mvikotlin.core.store.SimpleBootstrapper
import com.arkivanov.mvikotlin.core.store.StoreFactory
import com.fxrates.domain.repository.RatesRepository
import com.fxrates.feature.rates.list.mvi.RatesListStore.Action
import com.fxrates.feature.rates.list.mvi.RatesListStore.State
import me.tatarka.inject.annotations.Inject

@Inject
internal class RatesListStoreFactory(
    private val storeFactory: StoreFactory,
    private val repository: RatesRepository,
) {

    fun createStore(base: String): RatesListStore {
        val store = storeFactory.create(
            name = "RatesListStore",
            initialState = State(base = base),
            bootstrapper = SimpleBootstrapper(Action.LoadRates(base = base)),
            executorFactory = { RatesListExecutor(repository = repository) },
            reducer = { message -> reduce(message) },
        )
        return RatesListStore(store)
    }

}
package com.fxrates.feature.rates.list

import com.fxrates.core.format.NumberFormatter
import com.fxrates.core.money.RateChangeCalculator
import com.fxrates.core.utils.Empty
import com.fxrates.core.utils.Resource
import com.fxrates.domain.model.CurrencyRate
import com.fxrates.feature.rates.list.RatesListUiState.Content
import com.fxrates.feature.rates.list.model.RateItem
import com.fxrates.feature.rates.list.model.Trend
import com.fxrates.feature.rates.list.mvi.RatesListStore
import com.fxrates.ui.Strings
import me.tatarka.inject.annotations.Inject

@Inject
internal class RatesListUiStateConverter {

    fun createUiState(state: RatesListStore.State): RatesListUiState {
        val rates = state.rates
        val subtitle = when (rates) {
            is Resource.Data -> {
                rates.value.firstOrNull()?.let { rate -> Strings.ratesSubtitle(state.base, rate.date.toString()) }
                    ?: String.Empty
            }
            is Resource.Loading, is Resource.Error -> {
                String.Empty
            }
        }
        return RatesListUiState(
            subtitle = subtitle,
            query = state.query,
            isRefreshEnabled = rates !is Resource.Loading,
            content = createContent(rates = rates, query = state.query),
        )
    }

    private fun createContent(rates: Resource<List<CurrencyRate>>, query: String): Content = when (rates) {
        is Resource.Loading -> {
            Content.Loading
        }
        is Resource.Error -> {
            Content.Error
        }
        is Resource.Data -> {
            val items = rates.value
                .filter { rate -> rate.matches(query.trim()) }
                .map(::toItem)
            if (items.isEmpty()) Content.NothingFound else Content.Items(items)
        }
    }

    private fun CurrencyRate.matches(query: String): Boolean {
        return query.isEmpty() || code.contains(query, ignoreCase = true) || name.contains(query, ignoreCase = true)
    }

    private fun toItem(rate: CurrencyRate): RateItem {
        val change = rate.previousRate?.let { previous -> RateChangeCalculator.calculate(previous, rate.rate) }
        val trend = when {
            change == null || change.absolute.isZero() -> Trend.Flat
            change.absolute.isPositive -> Trend.Up
            else -> Trend.Down
        }
        return RateItem(
            code = rate.code,
            name = rate.name,
            rate = NumberFormatter.formatRate(rate.rate),
            change = change?.let { value -> NumberFormatter.formatSignedPercent(value.percent) },
            trend = trend,
        )
    }

}
package com.fxrates.feature.rates.list

import androidx.compose.runtime.Immutable
import com.fxrates.core.utils.Empty
import com.fxrates.feature.rates.list.model.RateItem

@Immutable
internal data class RatesListUiState(
    val subtitle: String = String.Empty,
    val query: String = String.Empty,
    val isRefreshEnabled: Boolean = false,
    val content: Content = Content.Loading,
) {

    @Immutable
    sealed class Content {

        data object Loading : Content()

        data object Error : Content()

        data object NothingFound : Content()

        data class Items(val items: List<RateItem>) : Content()

    }

}
package com.fxrates.ui

/**
 * Every user-facing string of the app. The app is English-only, so a constant is enough; a
 * string is never written inline in a composable.
 */
object Strings {

    const val RATES_TITLE = "Rates"
    const val RATES_SEARCH_HINT = "Search by code or name"
    const val RATES_NOTHING_FOUND = "Nothing found"
    const val ERROR_TITLE = "Could not load the rates"
    const val RETRY = "Retry"
    const val REFRESH = "Refresh"

    fun ratesSubtitle(base: String, date: String): String = "1 $base · $date"

}

